python -c "import datetime, os; from pathlib import Path; from PIL import Image, ImageDraw, ImageFont; from pypdf import PdfReader, PdfWriter; rp=Path('report.pdf');
if not rp.exists(): raise SystemExit('ERROR: report.pdf not found in current directory');
W,H=1275,1650; img=Image.new('RGB',(W,H),'white'); dr=ImageDraw.Draw(img);
cands=['/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf','/usr/share/fonts/truetype/dejavu/DejaVuSerif.ttf','/usr/share/fonts/TTF/DejaVuSans.ttf','/usr/share/fonts/dejavu/DejaVuSans.ttf'];
fp=next((c for c in cands if os.path.exists(c)),None); print('font:', fp if fp else 'built-in default');
title='Annual Financial Report'; date_str=datetime.date.today().strftime('%B %d, %Y');
ft=ImageFont.truetype(fp,110) if fp else ImageFont.load_default(); fd=ImageFont.truetype(fp,52) if fp else ImageFont.load_default();
bb=dr.textbbox((0,0),title,font=ft); tw=bb[2]-bb[0]; th=bb[3]-bb[1]; dr.text(((W-tw)/2-bb[0],int(H*0.30)),title,fill=(26,26,46),font=ft);
bb2=dr.textbbox((0,0),date_str,font=fd); tw2=bb2[2]-bb2[0]; dr.text(((W-tw2)/2-bb2[0],int(H*0.30)+th+60),date_str,fill=(85,85,85),font=fd);
dr.rectangle([(int(W*0.25),int(H*0.30)+th+28),(int(W*0.75),int(H*0.30)+th+36)],fill=(184,134,11));
img.save('cover_page.pdf','PDF',resolution=150.0);
rr=PdfReader('report.pdf'); cr=PdfReader('cover_page.pdf'); w=PdfWriter(); w.add_page(cr.pages[0]);
for p in rr.pages: w.add_page(p);
with open('report_with_cover.pdf','wb') as f: w.write(f);
print('SUCCESS: report_with_cover.pdf created | cover title: Annual Financial Report | cover date: '+date_str+' | original report.pdf pages: '+str(len(rr.pages))+' | total pages: '+str(len(w.pages)))"
